 void submit(boolean edit){if(working)return;String name=nameField.getText().toString().trim(),description=descriptionField.getText().toString();List<String> devices=devices();try{int players=edit?50:Integer.parseInt(playersField.getText().toString());double gravity=edit?196.2:Double.parseDouble(gravityField.getText().toString());ManagedProjects.validate(name,devices,players,gravity);if(description.length()>2000)throw new IOException("Description limit: 2000 characters.");String start=edit?"":startField.getText().toString().trim();if(!edit&&start.isEmpty())throw new IOException("Enter a start place name.");String template=edit?"":templateField.getSelectedItemPosition()==0?"baseplate":"empty";boolean streaming=!edit&&streamingField.isChecked();error="";working=true;run("Saving project",()->{if(edit){selected.data.put("name",name).put("description",description).put("devices",new JSONArray(devices));repo.save(selected);}else selected=repo.create(name,description,devices,template,start,players,gravity,streaming,a.session);},()->{working=false;open(selected);});}catch(Exception e){a.message("Check project settings",RobloxApi.safe(e));}}
 interface Work{void run()throws Exception;}
 void run(String label,Work work,Runnable done){ProgressDialog p=new ProgressDialog(a.dialogContext());p.setMessage(label+"…");p.setCancelable(false);p.setOnShowListener(v->a.roundDialog(p));p.show();int token=a.epoch;a.worker.execute(()->{try{work.run();a.runOnUiThread(()->{p.dismiss();working=false;if(token==a.epoch)done.run();});}catch(Exception e){a.runOnUiThread(()->{p.dismiss();working=false;if(token==a.epoch)a.message(label+" failed",RobloxApi.safe(e));});}});}
