 void addPlace(){LinearLayout box=a.vertical();box.setPadding(dp(20),dp(8),dp(20),0);EditText name=field(box,"Place name","New place",InputType.TYPE_CLASS_TEXT,false);Spinner template=spinner(box,"Template",new String[]{"Baseplate + spawn","Empty place"},0);a.dialogs().setTitle("Add a local place").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Create",(d,w)->run("Creating place",()->repo.addPlace(selected,name.getText().toString(),template.getSelectedItemPosition()==0?"baseplate":"empty"),()->refresh())).show();}
