 void rename(JSONObject p){EditText name=new EditText(a.dialogContext());name.setText(p.optString("name"));a.dialogs().setTitle("Place name").setView(name).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->run("Renaming place",()->{String s=name.getText().toString().trim();if(s.isEmpty()||s.length()>100)throw new IOException("Name must be 1–100 characters.");p.put("name",s);repo.save(selected);},()->refresh())).show();}
