 void link(JSONObject p){if(a.session==null){a.message("Connect Roblox first","Use your creator API key, then reopen this project.");return;}LinearLayout box=a.vertical();box.setPadding(dp(20),dp(8),dp(20),0);EditText universe=field(box,"Existing Universe ID",String.valueOf(selected.data.optJSONObject("cloud").optLong("universe_id",0)),InputType.TYPE_CLASS_NUMBER,false);EditText place=field(box,"Existing Place ID",p.optLong("cloud_place_id",0)>0?String.valueOf(p.optLong("cloud_place_id")):"",InputType.TYPE_CLASS_NUMBER,false);a.addText(box,"Publishing replaces this cloud place's content. One universe per project. Create new cloud experiences/places in desktop Studio first.",12,false,a.MUTED,8);a.dialogs().setTitle("Link an existing cloud place").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Verify & link",(d,w)->{RobloxApi.Session s=a.session;run("Verifying target",()->{long u=Long.parseLong(universe.getText().toString()),id=Long.parseLong(place.getText().toString());if(u<=0||id<=0)throw new IOException("Enter positive numeric IDs.");long existing=selected.data.optJSONObject("cloud").optLong("universe_id",0);if(existing>0&&existing!=u)throw new IOException("This project is linked to another universe. Duplicate it for a different target.");for(int n=0;n<selected.places().length();n++){JSONObject other=selected.places().getJSONObject(n);if(other!=p&&other.optLong("cloud_place_id",0)==id)throw new IOException("Another local place already uses this target.");}JSONObject remote=a.api.json(RobloxApi.ROOT+"/cloud/v2/universes/"+u+"/places/"+id,s.key,null);if(!("universes/"+u+"/places/"+id).equals(remote.optString("path")))throw new IOException("Roblox did not confirm the target place.");if(a.session!=s)throw new IOException("Account changed.");selected.data.optJSONObject("cloud").put("universe_id",u);p.put("cloud_place_id",id).put("last_upload",JSONObject.NULL);repo.save(selected);},()->refresh());}).show();}
 void uploadDialog(JSONObject p){if(a.session==null){a.message("Connect Roblox first","Reconnect before uploading.");return;}a.dialogs().setTitle("Save or publish this place").setItems(new String[]{"Save a cloud version (not live)","Publish a version (updates live place)"},(d,n)->a.dialogs().setTitle(n==0?"Save to Roblox?":"Publish to Roblox?").setMessage("Target: Universe "+selected.data.optJSONObject("cloud").optLong("universe_id")+" / Place "+p.optLong("cloud_place_id")+"\n\nThis uploads one place file and can overwrite its cloud content. Device targets, description and server-size plans are not applied. Requires universe-places:write. Publishing does not change public/private visibility.").setNegativeButton("Cancel",null).setPositiveButton(n==0?"Save version":"Publish version",(dd,w)->upload(p,n==1)).show()).show();}
 void upload(JSONObject p,boolean publish){if(working)return;working=true;RobloxApi.Session s=a.session;if(s==null){working=false;return;}run(publish?"Publishing version":"Saving cloud version",()->{File tmp=repo.stage(selected,p);try{String hash=ManagedProjects.hashFile(tmp);p.put("last_attempt",new JSONObject().put("time",System.currentTimeMillis()).put("state","Unconfirmed").put("type",publish?"Published":"Saved").put("sha256",hash));repo.save(selected);PublishService.Result result=PublishService.upload(s,selected.data.optJSONObject("cloud").optLong("universe_id"),p.optLong("cloud_place_id"),tmp,publish);JSONObject receipt=new JSONObject().put("version",result.version).put("type",result.type).put("time",System.currentTimeMillis()).put("sha256",hash).put("uploader_user_id",s.userId);p.put("last_upload",receipt).put("last_attempt",receipt);try{repo.save(selected);}catch(Exception e){throw new IOException("Roblox confirmed version "+result.version+", but its local receipt could not be saved. Check Creator Dashboard; do not blindly retry.");}}finally{tmp.delete();}},()->{refresh();a.message("Roblox confirmed the upload",p.optJSONObject("last_upload").optString("type")+" version "+p.optJSONObject("last_upload").optLong("version")+". Audience and device settings are unchanged.");});}
 void more(){a.dialogs().setTitle(selected.name()).setItems(new String[]{"Duplicate locally (no cloud links)","View project.yml","Open Creator Dashboard","Delete local project"},(d,n)->{if(n==0)run("Duplicating project",()->selected=repo.duplicate(selected),()->open(selected));if(n==1)run("Reading manifest",()->{String y=ManagedProjects.yaml(selected.data);a.runOnUiThread(()->{TextView text=a.text(y,12,false,a.INK);text.setTypeface(Typeface.MONOSPACE);text.setTextIsSelectable(true);text.setPadding(dp(18),dp(12),dp(18),dp(12));ScrollView scroll=new ScrollView(a);scroll.addView(text);a.dialogs().setTitle("project.yml").setView(scroll).setPositiveButton("Done",null).show();});},()->{});if(n==2)a.openBrowser("https://create.roblox.com/dashboard/creations");if(n==3)a.dialogs().setTitle("Delete this local project?").setMessage("Removes its local places and backups permanently. Export a ZIP first. No cloud experience is deleted.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(dd,w)->run("Deleting project",()->repo.deleteUri(selected.folder),()->{selected=null;a.navigate("projects");})).show();}).show();}
 void looseFile(ProjectStore.Project source){a.dialogs().setTitle(source.name).setItems(new String[]{"Open in 3D editor","Create a project from this file","File details"},(dialog,n)->{if(n==0){EngineActivity.launch(a,source.uri,source.name.replaceAll("(?i)\\.rbxlx?$",""),null,null);return;}if(n==2){a.message(source.name,source.size+" bytes\n"+source.location);return;}EditText name=new EditText(a.dialogContext());name.setText(source.name.replaceAll("(?i)\\.rbxlx?$",""));a.dialogs().setTitle("Create a project from file").setView(name).setMessage("Copies the file into a managed project. The original is kept; no cloud link is assumed.").setNegativeButton("Cancel",null).setPositiveButton("Create",(d,w)->run("Creating project",()->{String title=name.getText().toString();ManagedProjects.Record record=repo.create(title,"",Arrays.asList("Computer","Phone","Tablet"),"empty","Start place",50,196.2,false,a.session);try{File staged=a.store.stageLocal(source.uri);try{repo.replace(record,record.places().getJSONObject(0),staged);}finally{staged.delete();}selected=record;}catch(Exception e){try{repo.deleteUri(record.folder);}catch(Exception ignored){}throw e;}},()->open(selected))).show();}).show();}
 void pickZip(){if(!a.store.available()){a.message("Choose project storage","Select a folder first.");return;}a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE),303);}
 void importZip(Uri uri){run("Importing project ZIP",()->{File tmp=File.createTempFile("zip-import-",".zip",a.getCacheDir());try{try(InputStream in=a.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(tmp)){if(in==null)throw new IOException("Cannot read ZIP.");byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>300L*1024*1024)throw new IOException("ZIP exceeds 300 MiB.");out.write(b,0,n);}}selected=repo.importZip(tmp);}finally{tmp.delete();}},()->open(selected));}
 void export(){run("Preparing ZIP",()->pendingExport=repo.export(selected),()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,ManagedProjects.slug(selected.name())+".zip");a.startActivityForResult(i,301);});}
